/**
 * YARA modules: members used for completion, hover and lint.
 * The structure comes from libyara (modules-data.js, generated by scripts/yara-modules.mjs).
 *
 * Node kinds:
 *   function   pe.imports("kernel32.dll")    overloads: [{ args: ['string'], ret: 'integer' }]
 *   value      pe.number_of_sections         type: integer | string | float
 *   constant   pe.MACHINE_I386               integer
 *   struct     pe.linker_version.major       fields
 *   array      pe.sections[i].name           fields (array of structs) or type (array of values)
 *   dict       pe.version_info["x"]          fields or type
 */
import { MODULE_DATA } from './modules-data.js';

const signature = (name, node) => node.sig
    || node.overloads.map(o => `${name}(${o.args.join(', ')})${o.ret ? ' -> ' + o.ret : ''}`).join(' | ');

function prepare(fields) {
    for (const [name, node] of Object.entries(fields || {})) {
        if (node.kind === 'function') node.sig = signature(name, node);
        node.doc = node.doc || '';
        if (node.fields) prepare(node.fields);
    }
    return fields;
}

export const MODULES = Object.fromEntries(Object.entries(MODULE_DATA).map(([name, mod]) => [name, { ...mod, fields: prepare(mod.fields) }]));

export function resolvePath(path) {
    const mod = MODULES[path[0]];
    if (!mod) return null;
    let node = { kind: 'module', fields: mod.fields, doc: mod.doc };
    for (const part of path.slice(1)) {
        const fields = node.fields;
        if (!fields || !fields[part]) return null;
        node = fields[part];
    }
    return node;
}

/** Fields under a node, for completion after a dot. */
export function childrenOf(node) {
    if (!node) return {};
    if (node.kind === 'module' || node.kind === 'struct' || node.kind === 'array') return node.fields || {};
    return {};
}
